/** Browser file transfer vocabulary shared by picker, clipboard and drag/drop. */
export interface FileTransfer {
    files?: ArrayLike<File> | null;
    items?: ArrayLike<{
        kind: string;
        getAsFile(): File | null;
    }> | null;
    types?: readonly string[];
}
/** Prefer FileList; items is the fallback used by browsers that omit clipboard.files. */
export function filesFromTransfer(transfer: FileTransfer | null): File[] {
    if (!transfer)
        return [];
    const files = Array.from(transfer.files || []);
    return files.length ? files : Array.from(transfer.items || []).filter(item => item.kind === 'file').map(item => item.getAsFile()).filter((file): file is File => file !== null);
}
/** Capture file transfers before the original image-only editor; ordinary text is untouched. */
export function bindMaterialInputs(card: HTMLElement, receive: (files: File[]) => void, dragging: (active: boolean) => void = () => { }) {
    const hasFiles = (transfer: DataTransfer | null) => !!transfer && (Array.from(transfer.types).includes('Files') || Array.from(transfer.items).some(item => item.kind === 'file'));
    const paste = (event: ClipboardEvent) => { const files = filesFromTransfer(event.clipboardData); if (!files.length)
        return; event.preventDefault(); event.stopImmediatePropagation(); receive(files); };
    const over = (event: DragEvent) => { if (!hasFiles(event.dataTransfer))
        return; event.preventDefault(); event.stopImmediatePropagation(); if (event.dataTransfer)
        event.dataTransfer.dropEffect = 'copy'; dragging(true); };
    const leave = (event: DragEvent) => { if (!(event.relatedTarget instanceof Node) || !card.contains(event.relatedTarget))
        dragging(false); };
    const drop = (event: DragEvent) => { dragging(false); const files = filesFromTransfer(event.dataTransfer); if (!files.length)
        return; event.preventDefault(); event.stopImmediatePropagation(); receive(files); };
    card.addEventListener('paste', paste, true);
    card.addEventListener('dragover', over, true);
    card.addEventListener('dragleave', leave, true);
    card.addEventListener('drop', drop, true);
    return () => { card.removeEventListener('paste', paste, true); card.removeEventListener('dragover', over, true); card.removeEventListener('dragleave', leave, true); card.removeEventListener('drop', drop, true); dragging(false); };
}
